//! SSX 3 (USA) — native recompilation, windowed front end.
//!
//! Boots the recompiled EE code (`ssx3-ee`, generated by `recomp-ee`) on the
//! `ssx3-ps2` platform layer and presents GS output with `wgpu`.
//!
//! Keys (pad 1): arrows = d-pad, X = Cross, Z = Square, S = Circle, A = Triangle,
//! Enter = Start, Right Shift = Select, Q/W = L1/R1, 1/2 = L2/R2.
//! Game controllers (via gilrs) map to pad 1 too, analog sticks included; a
//! second controller drives pad 2 when `SSX3_PAD2=1` plugs it in (Multi Play).

// The generated EE code in the chosen form (features `ee-threads` / `ee-unwind`).
#[cfg(feature = "ee-unwind")]
extern crate ssx3_ee_unwind as ssx3_ee;
#[cfg(all(feature = "ee-threads", not(feature = "ee-unwind")))]
extern crate ssx3_ee_threads as ssx3_ee;

#[cfg(any(target_os = "android", test))]
mod android;
mod app;
mod game;
mod png;
mod present;
mod settings;

fn main() {
    app::run(winit::event_loop::EventLoop::builder());
}
